PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), email TEXT NOT NULL UNIQUE, displayName TEXT NOT NULL DEFAULT '', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS profiles (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), userId TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE, displayName TEXT NOT NULL DEFAULT '', createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, FOREIGN KEY(userId) REFERENCES users(publicId)) STRICT;
CREATE TABLE IF NOT EXISTS organizations (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), name TEXT NOT NULL, ownerId TEXT NOT NULL REFERENCES users(publicId), createdAt TEXT NOT NULL) STRICT;
CREATE TABLE IF NOT EXISTS memberships (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), organizationId TEXT NOT NULL REFERENCES organizations(publicId), userId TEXT NOT NULL REFERENCES users(publicId), role TEXT NOT NULL CHECK(role IN ('owner','admin','member')), createdAt TEXT NOT NULL, UNIQUE(organizationId,userId)) STRICT;
CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), organizationId TEXT NOT NULL REFERENCES organizations(publicId), name TEXT NOT NULL, status TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, UNIQUE(organizationId,publicId)) STRICT;
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), organizationId TEXT NOT NULL REFERENCES organizations(publicId), projectId TEXT NOT NULL REFERENCES projects(publicId), creatorId TEXT NOT NULL REFERENCES users(publicId), assigneeId TEXT REFERENCES users(publicId), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK(status IN ('todo','in_progress','done','cancelled')), priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','urgent')), dueDate TEXT, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, UNIQUE(organizationId,projectId,publicId), FOREIGN KEY(organizationId,projectId) REFERENCES projects(organizationId,publicId)) STRICT;
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), organizationId TEXT NOT NULL REFERENCES organizations(publicId), projectId TEXT NOT NULL REFERENCES projects(publicId), taskId TEXT NOT NULL REFERENCES tasks(publicId), authorId TEXT NOT NULL REFERENCES users(publicId), body TEXT NOT NULL, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL, UNIQUE(organizationId,projectId,publicId), FOREIGN KEY(organizationId,projectId) REFERENCES projects(organizationId,publicId), FOREIGN KEY(organizationId,projectId,taskId) REFERENCES tasks(organizationId,projectId,publicId)) STRICT;
CREATE TABLE IF NOT EXISTS activities (id INTEGER PRIMARY KEY, publicId TEXT NOT NULL UNIQUE CHECK(length(publicId)=15 AND publicId NOT GLOB '*[^a-z0-9]*'), organizationId TEXT NOT NULL REFERENCES organizations(publicId), projectId TEXT REFERENCES projects(publicId), actorId TEXT NOT NULL REFERENCES users(publicId), action TEXT NOT NULL, subjectType TEXT NOT NULL, subjectId TEXT NOT NULL, createdAt TEXT NOT NULL) STRICT;
CREATE INDEX IF NOT EXISTS memberships_org ON memberships(organizationId); CREATE INDEX IF NOT EXISTS memberships_user ON memberships(userId); CREATE INDEX IF NOT EXISTS projects_org ON projects(organizationId); CREATE INDEX IF NOT EXISTS tasks_tenant_project ON tasks(organizationId,projectId,createdAt,publicId); CREATE INDEX IF NOT EXISTS tasks_assignee ON tasks(assigneeId); CREATE INDEX IF NOT EXISTS comments_task ON comments(organizationId,projectId,taskId,createdAt,publicId); CREATE INDEX IF NOT EXISTS activities_org ON activities(organizationId,createdAt,publicId);
CREATE TRIGGER IF NOT EXISTS tasks_tenant_frozen BEFORE UPDATE OF organizationId,projectId,creatorId ON tasks WHEN NEW.organizationId<>OLD.organizationId OR NEW.projectId<>OLD.projectId OR NEW.creatorId<>OLD.creatorId BEGIN SELECT RAISE(ABORT,'tenant ownership is immutable'); END;
CREATE TRIGGER IF NOT EXISTS comments_tenant_frozen BEFORE UPDATE OF organizationId,projectId,taskId,authorId ON comments WHEN NEW.organizationId<>OLD.organizationId OR NEW.projectId<>OLD.projectId OR NEW.taskId<>OLD.taskId OR NEW.authorId<>OLD.authorId BEGIN SELECT RAISE(ABORT,'tenant ownership is immutable'); END;
CREATE TRIGGER IF NOT EXISTS task_activity AFTER INSERT ON tasks BEGIN INSERT INTO activities(publicId,organizationId,projectId,actorId,action,subjectType,subjectId,createdAt) VALUES(substr(lower(hex(randomblob(8))),1,15),NEW.organizationId,NEW.projectId,NEW.creatorId,'create','task',NEW.publicId,NEW.createdAt); END;
CREATE TRIGGER IF NOT EXISTS comment_activity AFTER INSERT ON comments BEGIN INSERT INTO activities(publicId,organizationId,projectId,actorId,action,subjectType,subjectId,createdAt) VALUES(substr(lower(hex(randomblob(8))),1,15),NEW.organizationId,NEW.projectId,NEW.authorId,'create','comment',NEW.publicId,NEW.createdAt); END;
